import com.primehr.integration.administrative.*;import com.primehr.integration.humanresource.*;import com.primehr.performancemanagement.api.PerformanceCommitmentDtos.*;import com.primehr.performancemanagement.domain.*;import com.primehr.performancemanagement.infrastructure.*;import com.primehr.shared.audit.PrimeHrAuditService;import com.primehr.shared.exception.*;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.time.*;import java.util.*;import java.util.stream.*;
@Service@Transactional public class PerformanceCommitmentServiceImpl implements PerformanceCommitmentService{
 @org.springframework.beans.factory.annotation.Autowired private PerformanceCommitmentRouteRepository routes;
 @org.springframework.beans.factory.annotation.Autowired private PerformanceCommitmentRouteStepRepository routeSteps;
 @org.springframework.beans.factory.annotation.Autowired private PerformanceCommitmentActionRepository actions;
 private final PerformanceCommitmentRepository roots;private final PerformanceCommitmentVersionRepository versions;private final PerformanceCommitmentSectionRepository sections;private final PerformanceCommitmentItemRepository items;private final PerformanceCommitmentCascadeRepository cascades;private final PerformancePlanAssignmentRepository assignments;private final PerformancePlanAssignmentObjectiveRepository assignmentObjectives;private final PerformanceCycleRepository cycles;private final PerformanceTemplateVersionRepository templates;private final PerformanceTemplateSectionRepository templateSections;private final PerformanceTemplateItemRepository templateItems;private final PerformanceSuccessIndicatorVersionRepository indicators;private final HumanResourcePerformanceParticipantClient humanResource;private final AdministrativePerformancePlanningClient administrative;private final PrimeHrAuditService audit;
 public PerformanceCommitmentServiceImpl(PerformanceCommitmentRepository r,PerformanceCommitmentVersionRepository v,PerformanceCommitmentSectionRepository s,PerformanceCommitmentItemRepository i,PerformanceCommitmentCascadeRepository ca,PerformancePlanAssignmentRepository a,PerformancePlanAssignmentObjectiveRepository ao,PerformanceCycleRepository cy,PerformanceTemplateVersionRepository t,PerformanceTemplateSectionRepository ts,PerformanceTemplateItemRepository ti,PerformanceSuccessIndicatorVersionRepository in,HumanResourcePerformanceParticipantClient hr,AdministrativePerformancePlanningClient ad,PrimeHrAuditService au){roots=r;versions=v;sections=s;items=i;cascades=ca;assignments=a;assignmentObjectives=ao;cycles=cy;templates=t;templateSections=ts;templateItems=ti;indicators=in;humanResource=hr;administrative=ad;audit=au;}
 @Override@Transactional(readOnly=true)public String formTypeForAssignment(String a,String id){return assignment(a,id).getSubjectType()==PerformancePlanAssignment.SubjectType.EMPLOYEE?"IPCR":"OPCR";}@Override@Transactional(readOnly=true)public String formTypeForVersion(String a,String id){return "EMPLOYEE".equals(version(a,id).getSubjectType())?"IPCR":"OPCR";}
 @Override public CommitmentResponse generate(String a,String assignmentId,String key,String actor,PermissionDataScope scope,String correlation){PerformancePlanAssignment p=assignment(a,assignmentId);if(scope!=PermissionDataScope.AGENCY_WIDE&&!p.getOwnerEmployeeNo().equalsIgnoreCase(actor))throw new AccessDeniedException("Assignment is outside the permitted ownership or assignment scope");return generate(a,assignmentId,key,actor,correlation);}
 @Override@Transactional(readOnly=true)public List<CommitmentResponse>list(String a,String actor,PermissionDataScope scope,CommitmentFilter f){return versions.findByAgencyIdOrderByCreatedAtDesc(a).stream().filter(v->v.getFormType().equalsIgnoreCase(f.formType())).filter(v->f.cycleId()==null||v.getCycleId().equals(f.cycleId())).filter(v->f.subjectType()==null||v.getSubjectType().equalsIgnoreCase(f.subjectType())).filter(v->f.subjectId()==null||Objects.equals(v.getSubjectId(),f.subjectId())).filter(v->f.ownerEmployeeNo()==null||v.getOwnerEmployeeNo().equalsIgnoreCase(f.ownerEmployeeNo())).filter(v->f.status()==null||v.getStatus().name().equalsIgnoreCase(f.status())).filter(v->visible(v,actor,scope)).filter(v->!Boolean.TRUE.equals(f.assignedTask())||currentTask(a,v,actor)).map(v->response(a,v)).toList();}
 @Override@Transactional(readOnly=true)public CommitmentResponse get(String a,String id,String actor,PermissionDataScope scope){PerformanceCommitmentVersion v=version(a,id);access(v,actor,scope);return response(a,v);}
 @Override public CommitmentResponse generate(String a,String assignmentId,String key,String actor,String correlation){required(key,"idempotencyKey");var existing=roots.findByAgencyIdAndAssignmentId(a,assignmentId);if(existing.isPresent())return response(a,version(a,existing.get().getCurrentVersionId()));PerformancePlanAssignment p=assignment(a,assignmentId);if(p.getStatus()!=PerformancePlanAssignment.Status.ACTIVE)throw new IllegalArgumentException("Commitments require an active plan assignment");PerformanceCycle cycle=cycles.findByIdAndAgencyId(p.getCycleId(),a).orElseThrow(()->new ResourceNotFoundException("Performance cycle not found"));if(cycle.getStatus()!=PerformanceCycle.Status.OPEN)throw new IllegalArgumentException("Commitments require an open cycle");PerformanceTemplateVersion template=templates.findByIdAndAgencyId(p.getTemplateVersionId(),a).orElseThrow(()->new ResourceNotFoundException("Performance template version not found"));List<PerformanceTemplateSection> sourceSections=templateSections.findByAgencyIdAndTemplateVersionIdOrderByDisplayOrder(a,template.getId());validateStructure(a,sourceSections);List<String> objectiveIds=assignmentObjectives.findByAgencyIdAndAssignmentIdOrderByDisplayOrder(a,assignmentId).stream().map(PerformancePlanAssignmentObjective::getObjectiveVersionId).toList();String assignmentFp=fp(join(p.getId(),p.getVersion(),p.getCycleId(),p.getTemplateVersionId(),p.getOrganizationFingerprint(),p.getParticipantFingerprint(),p.getRouteFingerprint(),objectiveIds));PerformanceCommitment root=roots.saveAndFlush(new PerformanceCommitment(a,assignmentId));PerformanceCommitmentVersion v=versions.saveAndFlush(new PerformanceCommitmentVersion(a,root.getId(),assignmentId,1,null,cycle,template,p,String.join(",",objectiveIds),assignmentFp,fp("empty"),Instant.now()));for(PerformanceTemplateSection source:sourceSections){PerformanceCommitmentSection section=sections.saveAndFlush(new PerformanceCommitmentSection(a,v.getId(),source));for(PerformanceTemplateItem item:templateItems.findByAgencyIdAndSectionIdOrderByDisplayOrder(a,source.getId())){PerformanceSuccessIndicatorVersion indicator=indicators.findByIdAndAgencyId(item.getIndicatorVersionId(),a).orElseThrow(()->new ResourceNotFoundException("Template indicator version not found"));items.save(new PerformanceCommitmentItem(a,v.getId(),section.getId(),item,indicator,indicatorFingerprint(indicator)));}}items.flush();v.contentChanged(contentFingerprint(a,v.getId()));v=versions.saveAndFlush(v);root.current(v.getId());roots.saveAndFlush(root);audit.record(a,"GENERATE_PERFORMANCE_COMMITMENT","SPMS_COMMITMENT_VERSION",v.getId(),1,v.getVersion(),null,response(a,v),null,correlation);return response(a,v);}
 @Override public CommitmentResponse replaceTargets(String a,String id,TargetReplacement input,String token,String actor,PermissionDataScope scope,String correlation){PerformanceCommitmentVersion v=version(a,id);access(v,actor,scope);editable(v);check(v.getVersion(),input.recordVersion());var before=response(a,v);List<PerformanceCommitmentItem> stored=items.findByAgencyIdAndCommitmentVersionIdOrderByCommitmentSectionIdAscDisplayOrderAsc(a,id);Map<String,TargetInput> commands=input.items().stream().collect(Collectors.toMap(TargetInput::itemId,x->x,(x,y)->{throw new IllegalArgumentException("Target item IDs must be unique");},LinkedHashMap::new));if(!commands.keySet().equals(stored.stream().map(PerformanceCommitmentItem::getId).collect(Collectors.toSet())))throw new IllegalArgumentException("Targets must atomically cover every commitment item");for(PerformanceCommitmentItem item:stored){TargetInput c=commands.get(item.getId());validateTarget(v,item,c);HumanResourceAssessmentSubject owner=null;if(c.responsibleEmployeeId()!=null){owner=humanResource.get(c.responsibleEmployeeId(),token);var membership=administrative.membership(c.responsibleEmployeeId(),token);if(v.getAreaId()!=null&&!Objects.equals(v.getAreaId(),membership.areaId())||"BUSINESS_UNIT".equals(v.getSubjectType())&&!Objects.equals(v.getBusinessUnitId(),membership.businessUnitId()))throw new IllegalArgumentException("Responsible owner must belong to the commitment organization");}item.target(c.committedValue(),c.committedFrom(),c.committedTo(),c.targetStart(),c.targetEnd(),c.deliverableClarification(),owner==null?null:owner.employeeId(),owner==null?null:owner.employeeNo(),owner==null?null:owner.displayName(),owner==null?null:owner.sourceFingerprint(),c.planningRemarks(),c.evidenceClarification());}items.saveAll(stored);items.flush();v.contentChanged(contentFingerprint(a,id));v=versions.saveAndFlush(v);audit.record(a,"REPLACE_PERFORMANCE_COMMITMENT_TARGETS","SPMS_COMMITMENT_VERSION",id,v.getDefinitionVersion(),v.getVersion(),before,response(a,v),null,correlation);return response(a,v);}
 @Override public CommitmentResponse replaceCascades(String a,String id,CascadeReplacement input,String actor,PermissionDataScope scope,String correlation){PerformanceCommitmentVersion v=version(a,id);access(v,actor,scope);editable(v);check(v.getVersion(),input.recordVersion());var before=response(a,v);List<PerformanceCommitmentItem> downstream=items.findByAgencyIdAndCommitmentVersionIdOrderByCommitmentSectionIdAscDisplayOrderAsc(a,id);Set<String> downstreamIds=downstream.stream().map(PerformanceCommitmentItem::getId).collect(Collectors.toSet());List<CascadeInput> commands=input.cascades()==null?List.of():input.cascades();Set<String> keys=new HashSet<>();List<PerformanceCommitmentCascade> replacement=new ArrayList<>();for(CascadeInput c:commands){if(!downstreamIds.contains(c.downstreamItemId()))throw new IllegalArgumentException("Cascade downstream item must belong to the edited commitment");PerformanceCommitmentItem up=item(a,c.upstreamItemId()),down=item(a,c.downstreamItemId());PerformanceCommitmentVersion upstream=version(a,up.getCommitmentVersionId());if(upstream.getStatus()!=PerformanceCommitmentVersion.Status.APPROVED)throw new IllegalArgumentException("Cascade upstream commitment must be approved");if(!upstream.getCycleId().equals(v.getCycleId()))throw new IllegalArgumentException("Cascade items must share the same cycle");compatible(up,down);String edge=c.upstreamItemId()+"|"+c.downstreamItemId()+"|"+c.mode();if(!keys.add(edge))throw new IllegalArgumentException("Duplicate cascade edge");replacement.add(new PerformanceCommitmentCascade(a,c.upstreamItemId(),c.downstreamItemId(),c.mode(),c.sharePercent(),fp(join(upstream.getContentFingerprint(),up.getIndicatorFingerprint(),down.getIndicatorFingerprint()))));}validateSharesAndCycles(a,downstreamIds,replacement);cascades.deleteByAgencyIdAndDownstreamItemIdIn(a,downstreamIds);cascades.flush();cascades.saveAll(replacement);cascades.flush();v.contentChanged(contentFingerprint(a,id));v=versions.saveAndFlush(v);audit.record(a,"REPLACE_PERFORMANCE_COMMITMENT_CASCADES","SPMS_COMMITMENT_VERSION",id,v.getDefinitionVersion(),v.getVersion(),before,response(a,v),null,correlation);return response(a,v);}
 @Override@Transactional(readOnly=true)public Readiness readiness(String a,String id,String token,String actor,PermissionDataScope scope){PerformanceCommitmentVersion v=version(a,id);access(v,actor,scope);List<String> errors=new ArrayList<>();try{HumanResourceAssessmentSubject owner=humanResource.get(v.getOwnerEmployeeId(),token);if(!Objects.equals(owner.sourceFingerprint(),v.getParticipantFingerprint()))errors.add("Accountable owner appointment source changed");if("EMPLOYEE".equals(v.getSubjectType())){var m=administrative.membership(v.getOwnerEmployeeId(),token);if(!Objects.equals(m.sourceFingerprint(),v.getOrganizationFingerprint()))errors.add("Employee organization membership source changed");}else{var o=administrative.organization(v.getSubjectType(),v.getSubjectId(),token);if(!Objects.equals(o.sourceFingerprint(),v.getOrganizationFingerprint()))errors.add("Organization source changed");}}catch(RuntimeException e){errors.add("Authoritative owner or organization source is unavailable");}for(PerformanceCommitmentItem i:items.findByAgencyIdAndCommitmentVersionIdOrderByCommitmentSectionIdAscDisplayOrderAsc(a,id)){try{validateTarget(v,i,new TargetInput(i.getId(),i.getCommittedValue(),i.getCommittedFrom(),i.getCommittedTo(),i.getTargetStart(),i.getTargetEnd(),i.getDeliverableClarification(),i.getResponsibleEmployeeId(),i.getPlanningRemarks(),i.getEvidenceClarification()));}catch(RuntimeException e){errors.add(i.getLabel()+": "+e.getMessage());}if(i.getResponsibleEmployeeId()!=null){try{var person=humanResource.get(i.getResponsibleEmployeeId(),token);var membership=administrative.membership(i.getResponsibleEmployeeId(),token);if(!Objects.equals(person.sourceFingerprint(),i.getResponsibleFingerprint())||v.getAreaId()!=null&&!Objects.equals(v.getAreaId(),membership.areaId())||"BUSINESS_UNIT".equals(v.getSubjectType())&&!Objects.equals(v.getBusinessUnitId(),membership.businessUnitId()))errors.add(i.getLabel()+": responsible owner source changed");}catch(RuntimeException e){errors.add(i.getLabel()+": responsible owner source is unavailable or stale");}}}return new Readiness(errors.isEmpty(),errors);}
 private void validateStructure(String a,List<PerformanceTemplateSection> ss){if(ss.isEmpty()||sum(ss.stream().map(PerformanceTemplateSection::getWeightPercent).toList()).compareTo(new BigDecimal("100.0000"))!=0)throw new IllegalArgumentException("Template section weights must total 100.0000");for(var s:ss){var its=templateItems.findByAgencyIdAndSectionIdOrderByDisplayOrder(a,s.getId());if(its.isEmpty()||sum(its.stream().map(PerformanceTemplateItem::getWeightPercent).toList()).compareTo(new BigDecimal("100.0000"))!=0)throw new IllegalArgumentException("Each template section item weight must total 100.0000");}}
 private static void validateTarget(PerformanceCommitmentVersion v,PerformanceCommitmentItem i,TargetInput c){if(c.targetStart()==null||c.targetEnd()==null||c.targetEnd().isBefore(c.targetStart())||c.targetStart().isBefore(v.getPeriodStart())||c.targetEnd().isAfter(v.getPeriodEnd()))throw new IllegalArgumentException("Target period must be ordered and within the cycle");if("WITHIN_RANGE".equals(i.getDirection())){if(c.committedFrom()==null||c.committedTo()==null||c.committedTo().compareTo(c.committedFrom())<0||c.committedValue()!=null)throw new IllegalArgumentException("WITHIN_RANGE requires only an ordered from/to target");}else if("MANUAL_RUBRIC".equals(i.getDirection())){if(c.committedValue()!=null||c.committedFrom()!=null||c.committedTo()!=null)throw new IllegalArgumentException("MANUAL_RUBRIC does not accept numeric targets");if(i.isRequired()&&(c.deliverableClarification()==null||c.deliverableClarification().isBlank()))throw new IllegalArgumentException("Required manual rubric items need deliverable clarification");}else if(c.committedValue()==null||c.committedFrom()!=null||c.committedTo()!=null)throw new IllegalArgumentException("This direction requires only committedValue");}
 private void validateSharesAndCycles(String a,Set<String> replaced,List<PerformanceCommitmentCascade> replacement){List<PerformanceCommitmentCascade> all=cascades.findByAgencyIdAndActiveTrue(a).stream().filter(e->!replaced.contains(e.getDownstreamItemId())).collect(Collectors.toCollection(ArrayList::new));all.addAll(replacement);Map<String,BigDecimal> shares=new HashMap<>();Map<String,List<String>> graph=new HashMap<>();for(var e:all){graph.computeIfAbsent(e.getUpstreamItemId(),x->new ArrayList<>()).add(e.getDownstreamItemId());if(e.getMode()==PerformanceCommitmentCascade.Mode.RESPONSIBILITY_SHARE)shares.merge(e.getUpstreamItemId(),e.getSharePercent(),BigDecimal::add);}if(shares.values().stream().anyMatch(x->x.compareTo(new BigDecimal("100.0000"))>0))throw new IllegalArgumentException("Active outgoing responsibility shares cannot exceed 100.0000");for(String node:graph.keySet())if(cycle(node,graph,new HashSet<>(),new HashSet<>()))throw new IllegalArgumentException("Cascade graph must be acyclic");}
 private static boolean cycle(String n,Map<String,List<String>>g,Set<String>visiting,Set<String>done){if(done.contains(n))return false;if(!visiting.add(n))return true;for(String x:g.getOrDefault(n,List.of()))if(cycle(x,g,visiting,done))return true;visiting.remove(n);done.add(n);return false;}private static void compatible(PerformanceCommitmentItem a,PerformanceCommitmentItem b){if(!a.getIndicatorVersionId().equals(b.getIndicatorVersionId())||!a.getMeasureType().equals(b.getMeasureType())||!a.getUnitOfMeasure().equalsIgnoreCase(b.getUnitOfMeasure())||!a.getDirection().equals(b.getDirection()))throw new IllegalArgumentException("Cascade items have incompatible indicator, measure, unit, or direction");}
 private CommitmentResponse response(String a,PerformanceCommitmentVersion v){List<PerformanceCommitmentItem> all=items.findByAgencyIdAndCommitmentVersionIdOrderByCommitmentSectionIdAscDisplayOrderAsc(a,v.getId());Map<String,List<PerformanceCommitmentItem>> bySection=all.stream().collect(Collectors.groupingBy(PerformanceCommitmentItem::getCommitmentSectionId,LinkedHashMap::new,Collectors.toList()));List<SectionResponse> ss=sections.findByAgencyIdAndCommitmentVersionIdOrderByDisplayOrder(a,v.getId()).stream().map(s->new SectionResponse(s.getId(),s.getSectionType(),s.getSectionCode(),s.getTitle(),s.getDescription(),s.getWeightPercent(),s.getDisplayOrder(),bySection.getOrDefault(s.getId(),List.of()).stream().map(this::itemResponse).toList())).toList();List<CascadeResponse> cs=cascades.findByAgencyIdAndDownstreamItemIdIn(a,all.stream().map(PerformanceCommitmentItem::getId).toList()).stream().map(c->new CascadeResponse(c.getId(),c.getUpstreamItemId(),c.getDownstreamItemId(),c.getMode().name(),c.getSharePercent(),c.getSourceFingerprint())).toList();return new CommitmentResponse(v.getId(),v.getCommitmentId(),v.getAssignmentId(),v.getDefinitionVersion(),v.getSupersedesId(),v.getCycleId(),v.getPolicyVersionId(),v.getTemplateVersionId(),v.getRatingScaleVersionId(),v.getObjectiveVersionIds()==null?List.of():Arrays.asList(v.getObjectiveVersionIds().split(",")),v.getFormType(),v.getFormLabel(),v.getPeriodStart(),v.getPeriodEnd(),v.getCalendarRevision(),v.getSubjectType(),v.getSubjectId(),v.getSubjectCode(),v.getSubjectName(),v.getAreaId(),v.getAreaName(),v.getBusinessUnitId(),v.getBusinessUnitName(),v.getOwnerEmployeeId(),v.getOwnerEmployeeNo(),v.getOwnerName(),v.getOwnerAppointmentId(),v.getOwnerJobPositionId(),v.getOwnerPlantillaId(),v.getOrganizationFingerprint(),v.getParticipantFingerprint(),v.getAssignmentFingerprint(),v.getContentFingerprint(),v.getSourceFetchedAt(),v.getStatus().name(),v.getContentRevision(),v.getLifecycleRevision(),v.getVersion(),ss,cs);}
 private ItemResponse itemResponse(PerformanceCommitmentItem i){return new ItemResponse(i.getId(),i.getCommitmentSectionId(),i.getIndicatorVersionId(),i.getLabel(),i.getOutputDescription(),i.getKeyResultArea(),i.getPerformanceIndicator(),i.getSuccessStatement(),i.getMeasureType(),i.getUnitOfMeasure(),i.getDirection(),i.getWeightPercent(),i.isRequired(),i.isSourceRequiresEvidence(),i.getSourceEvidenceRequirement(),i.getIndicatorFingerprint(),i.getCommittedValue(),i.getCommittedFrom(),i.getCommittedTo(),i.getTargetStart(),i.getTargetEnd(),i.getDeliverableClarification(),i.getResponsibleEmployeeId(),i.getResponsibleEmployeeNo(),i.getResponsibleName(),i.getPlanningRemarks(),i.getEvidenceClarification(),i.getDisplayOrder());}
 private String contentFingerprint(String a,String v){List<PerformanceCommitmentItem> owned=items.findByAgencyIdAndCommitmentVersionIdOrderByCommitmentSectionIdAscDisplayOrderAsc(a,v);String itemText=owned.stream().map(i->join(i.getId(),i.getIndicatorFingerprint(),i.getCommittedValue(),i.getCommittedFrom(),i.getCommittedTo(),i.getTargetStart(),i.getTargetEnd(),i.getDeliverableClarification(),i.getResponsibleEmployeeId(),i.getResponsibleFingerprint(),i.getPlanningRemarks(),i.getEvidenceClarification())).collect(Collectors.joining("||"));String cascadeText=cascades.findByAgencyIdAndDownstreamItemIdIn(a,owned.stream().map(PerformanceCommitmentItem::getId).toList()).stream().sorted(Comparator.comparing(PerformanceCommitmentCascade::getUpstreamItemId).thenComparing(PerformanceCommitmentCascade::getDownstreamItemId)).map(c->join(c.getUpstreamItemId(),c.getDownstreamItemId(),c.getMode(),c.getSharePercent(),c.getSourceFingerprint())).collect(Collectors.joining("||"));return fp(itemText+"##"+cascadeText);}private static String indicatorFingerprint(PerformanceSuccessIndicatorVersion i){return fp(join(i.getId(),i.getPolicyVersionId(),i.getRatingScaleVersionId(),i.getTitle(),i.getOutputDescription(),i.getKeyResultArea(),i.getPerformanceIndicator(),i.getSuccessStatement(),i.getMeasureType(),i.getUnitOfMeasure(),i.getDirection(),i.getTargetValue(),i.getTargetFrom(),i.getTargetTo(),i.isRequiresEvidence(),i.getEvidenceRequirements()));}
 private boolean visible(PerformanceCommitmentVersion v,String actor,PermissionDataScope scope){if(scope==PermissionDataScope.AGENCY_WIDE||v.getOwnerEmployeeNo().equalsIgnoreCase(actor))return true;if(scope!=PermissionDataScope.ASSIGNED_RECORDS)return false;return routes.findFirstByAgencyIdAndCommitmentVersionIdOrderByRouteRevisionDesc(v.getAgencyId(),v.getId()).stream().flatMap(r->routeSteps.findByAgencyIdAndRouteIdOrderByLevelAsc(v.getAgencyId(),r.getId()).stream()).anyMatch(s->s.getEmployeeNo().equalsIgnoreCase(actor));}private boolean currentTask(String a,PerformanceCommitmentVersion v,String actor){return routes.findFirstByAgencyIdAndCommitmentVersionIdOrderByRouteRevisionDesc(a,v.getId()).stream().filter(r->r.getStatus()==PerformanceCommitmentRoute.Status.ACTIVE).flatMap(r->routeSteps.findByAgencyIdAndRouteIdAndLevel(a,r.getId(),r.getCurrentLevel()).stream()).anyMatch(s->s.getStatus()==PerformanceCommitmentRouteStep.Status.CURRENT&&s.getEmployeeNo().equalsIgnoreCase(actor));}private void access(PerformanceCommitmentVersion v,String actor,PermissionDataScope scope){if(!visible(v,actor,scope))throw new AccessDeniedException("Commitment is outside the permitted ownership or assignment scope");}private PerformancePlanAssignment assignment(String a,String id){return assignments.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Performance plan assignment not found"));}private PerformanceCommitmentVersion version(String a,String id){return versions.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Performance commitment version not found"));}private PerformanceCommitmentItem item(String a,String id){return items.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Performance commitment item not found"));}private static BigDecimal sum(List<BigDecimal>x){return x.stream().reduce(BigDecimal.ZERO,BigDecimal::add).setScale(4,RoundingMode.HALF_UP);}private static void check(long actual,Long expected){if(expected==null||actual!=expected)throw new OptimisticConflictException("Expected recordVersion "+expected+" but current version is "+actual);}private static String required(String v,String n){if(v==null||v.isBlank())throw new IllegalArgumentException(n+" is required");return v.trim();}private static String join(Object...v){return Arrays.stream(v).map(x->x==null?"":x.toString().trim()).collect(Collectors.joining("|"));}private static String fp(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 @Override public CommitmentResponse amend(String a,String id,AmendmentCommand input,String actor,PermissionDataScope scope,String correlation){PerformanceCommitmentVersion source=version(a,id);access(source,actor,scope);if(input.reason()==null||input.reason().isBlank())throw new IllegalArgumentException("An amendment reason is required");var priorAction=actions.findByAgencyIdAndCommitmentVersionIdAndRequestKey(a,id,input.requestKey());if(priorAction.isPresent()){if(priorAction.get().getType()!=PerformanceCommitmentAction.Type.AMEND)throw new OptimisticConflictException("requestKey was already used for another action");return response(a,versions.findByAgencyIdAndSupersedesId(a,id).orElseThrow(()->new IllegalStateException("Amendment successor was not found")));}check(source.getVersion(),input.recordVersion());if(source.getStatus()!=PerformanceCommitmentVersion.Status.APPROVED)throw new IllegalStateException("Only an approved commitment may create an amendment draft");int number=versions.findByAgencyIdAndCommitmentIdOrderByDefinitionVersionDesc(a,source.getCommitmentId()).stream().findFirst().map(PerformanceCommitmentVersion::getDefinitionVersion).orElse(0)+1;PerformanceCommitmentVersion successor=versions.saveAndFlush(new PerformanceCommitmentVersion(a,source,number,fp("pending"),Instant.now()));Map<String,String> itemMap=new HashMap<>();for(PerformanceCommitmentSection oldSection:sections.findByAgencyIdAndCommitmentVersionIdOrderByDisplayOrder(a,id)){PerformanceTemplateSection templateSection=templateSections.findById(oldSection.getSourceSectionId()).filter(x->x.getAgencyId().equals(a)).orElseThrow(()->new IllegalStateException("Source template section was not found"));PerformanceCommitmentSection newSection=sections.saveAndFlush(new PerformanceCommitmentSection(a,successor.getId(),templateSection));for(PerformanceCommitmentItem oldItem:items.findByAgencyIdAndCommitmentVersionIdOrderByCommitmentSectionIdAscDisplayOrderAsc(a,id).stream().filter(x->x.getCommitmentSectionId().equals(oldSection.getId())).toList()){PerformanceTemplateItem templateItem=templateItems.findById(oldItem.getSourceItemId()).filter(x->x.getAgencyId().equals(a)).orElseThrow(()->new IllegalStateException("Source template item was not found"));PerformanceSuccessIndicatorVersion indicator=indicators.findByIdAndAgencyId(oldItem.getIndicatorVersionId(),a).orElseThrow(()->new IllegalStateException("Source indicator was not found"));PerformanceCommitmentItem copy=items.saveAndFlush(new PerformanceCommitmentItem(a,successor.getId(),newSection.getId(),templateItem,indicator,oldItem.getIndicatorFingerprint()));copy.target(oldItem.getCommittedValue(),oldItem.getCommittedFrom(),oldItem.getCommittedTo(),oldItem.getTargetStart(),oldItem.getTargetEnd(),oldItem.getDeliverableClarification(),oldItem.getResponsibleEmployeeId(),oldItem.getResponsibleEmployeeNo(),oldItem.getResponsibleName(),oldItem.getResponsibleFingerprint(),oldItem.getPlanningRemarks(),oldItem.getEvidenceClarification());items.saveAndFlush(copy);itemMap.put(oldItem.getId(),copy.getId());}}List<PerformanceCommitmentCascade> incoming=cascades.findByAgencyIdAndDownstreamItemIdIn(a,new ArrayList<>(itemMap.keySet()));for(var edge:incoming)cascades.save(new PerformanceCommitmentCascade(a,edge.getUpstreamItemId(),itemMap.get(edge.getDownstreamItemId()),edge.getMode(),edge.getSharePercent(),edge.getSourceFingerprint()));cascades.flush();successor.contentChanged(contentFingerprint(a,successor.getId()));successor=versions.saveAndFlush(successor);PerformanceCommitment root=roots.findByIdAndAgencyId(source.getCommitmentId(),a).orElseThrow(()->new IllegalStateException("Commitment root was not found"));root.current(successor.getId());roots.saveAndFlush(root);actions.saveAndFlush(new PerformanceCommitmentAction(a,source.getId(),null,null,PerformanceCommitmentAction.Type.AMEND,input.requestKey(),actor,source.getStatus().name(),successor.getStatus().name(),successor.getContentRevision(),successor.getLifecycleRevision(),null,input.reason(),null,Instant.now()));audit.record(a,"CREATE_PERFORMANCE_COMMITMENT_AMENDMENT","SPMS_COMMITMENT_VERSION",successor.getId(),successor.getDefinitionVersion(),successor.getVersion(),response(a,source),response(a,successor),input.reason(),correlation);return response(a,successor);}
 private static void editable(PerformanceCommitmentVersion v){if(v.getStatus()!=PerformanceCommitmentVersion.Status.DRAFT&&v.getStatus()!=PerformanceCommitmentVersion.Status.AMENDMENT_DRAFT&&v.getStatus()!=PerformanceCommitmentVersion.Status.RETURNED)throw new IllegalArgumentException("Only draft, amendment-draft, or returned commitments may be edited");}
}
